def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    from datetime import time

    if value is None:
        return None

    # If it's already a datetime.time object, convert to string
    if isinstance(value, time):
        return value.strftime("%H:%M:%S") if value.microsecond == 0 else value.strftime("%H:%M:%S.%f")

    # If it's a string, try to parse it and then format
    if isinstance(value, str):
        try:
            from datetime import datetime
            # Try common formats
            for fmt in ("%H:%M:%S.%f", "%H:%M:%S", "%H:%M"):
                try:
                    t = datetime.strptime(value, fmt).time()
                    return t.strftime("%H:%M:%S") if t.microsecond == 0 else t.strftime("%H:%M:%S.%f")
                except ValueError:
                    continue
        except Exception:
            pass
        return value

    # For other types, convert to string
    return str(value)
