def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    base = Point

    class _Point(base):
        _srid = srid_map
        _fields = fields

        def __init__(self, *args, **kwargs):
            # Dynamically assign attributes based on the fields
            for i, f in enumerate(self._fields):
                if i < len(args):
                    setattr(self, f, args[i])
                elif f in kwargs:
                    setattr(self, f, kwargs[f])
                else:
                    raise ValueError(f"Missing argument for field: {f}")

        def __repr__(self):
            val_str = ", ".join(f"{f}={getattr(self, f)!r}" for f in self._fields)
            return f"{self.__class__.__name__}({val_str})"

    _Point.__name__ = name
    _Point.__qualname__ = name
    return _Point

