def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str) or not s:
        raise ValueError("Input must be a non-empty string")

    parts = s.split('.')
    version = []
    for part in parts:
        # Extract leading digits
        num_str = ''
        for char in part:
            if char.isdigit():
                num_str += char
            else:
                break

        if num_str:
            version.append(int(num_str))
        else:
            # If no digits found, default to 0 for that component
            version.append(0)

    return tuple(version)

