    def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
        """Return attribute names and descriptions defined by interface."""

        names = []
        descriptions = {}

        # Go through this interface and all its ancestors (if all=True)
        for attr in self.interfaces():
            if all:
                for ancestor in attr.mro():
                    for name in [
                        n for n in ancestor.__dict__
                        if not n.startswith('_') and not callable(ancestor.__dict__[n])
                    ]:
                        if name not in names:
                            names.append(name)
                            descriptions[name] = ancestor.__dict__[name].__doc__ or ''
            else:
                for name in [
                    n for n in attr.__dict__
                    if not n.startswith('_') and not callable(attr.__dict__[n])
                ]:
                    if name not in names:
                        names.append(name)
                        descriptions[name] = attr.__dict__[name].__doc__ or ''

        return names, descriptions
