def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Check for infinite values
    if np.any(np.isinf(edges)):
        return np.cumprod(bins)

    # Check for invalid bin ranges
    for i in range(len(edges) - 1):
        if edges[i + 1] <= edges[i]:
            raise ValueError('Edges must be monotonically increasing.')

    # Compute the integral (sum of bin values multiplied by the width of each bin)
    integral_value = 0.0
    for i in range(len(edges) - 1):
        width = edges[i + 1] - edges[i]
        integral_value += bins[i] * width

    return integral_value

