def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    try:
        for observer_field in observer_schema:
            if isinstance(observer_field, dict):
                for field in observer_field:
                    if field not in last_applied_manifest:
                        last_applied_manifest[field] = None
                    if field in response:
                        last_applied_manifest[field] = response[field]
            elif isinstance(observer_field, list):
                for field in observer_field:
                    if field not in last_applied_manifest:
                        last_applied_manifest[field] = None
                    if field in response:
                        last_applied_manifest[field] = response[field]
            else:
                if observer_field not in last_applied_manifest:
                    last_applied_manifest[observer_field] = None
                if observer_field in response:
                    last_applied_manifest[observer_field] = response[observer_field]
    except KeyError as e:
        raise KeyError(f"Observed field {e} is not present in the Kubernetes response")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Access the manifest from the application spec
        manifest = app.spec.manifest
        if manifest is None:
            return

        # Ensure the observer section exists in the args
        if not hasattr(app.spec, 'args') or app.spec.args is None:
            app.spec.args = {}

        # Ensure the observers dictionary exists
        if 'observers' not in app.spec.args:
            app.spec.args['observers'] = {}

        observers = app.spec.args['observers']

        # Iterate over each resource in the manifest
        for resource_name, resource in manifest.items():
            # Check if a custom observer schema is already specified
            if resource_name not in observers:
                # Generate the default observer schema for the resource
                # The default schema typically monitors the status/subStatus of the resource
                default_schema = {
                    'kind': {
                        'schema': {
                            'type': 'object',
                            'properties': {
                                'status': {
                                    'type': 'object'
                                }
                            }
                        }
                    }
                }
                observers[resource_name] = default_schema
    except Exception as e:
        # Log the error or handle it appropriately
        raise e

