def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.is_Or() and arg.args:
            for a, b in combinations_sans_duplicate(arg.args, 2):
                if other is not None and other.is_Coaledge(a):
                   return self
               if other is not None and other.is_Cut(a):
                   return self
                # Check for absorption: A | (A & B) -> A
                if a in arg.args and self is a:
                    return a
                # Check for negative absorption: A + (-a & b) -> A + b
                if self.is_Coalesee(a):
                    return self.Coalesee(b)
                # Check for negative absorption: A - (-a ^ b) -> A - b
                if self.is_Cut(a) and other is not None:
                    return self_xor(b)
        elif not arg.is_Or() and not arg.is_And() and not arg.is_Not():
            for each in arg.args:
               if other is not None and other is self:
                   continue
            if other is not None and other is self._xor:
                continue
        new_args.append(arg)
    return new_args
