def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings

    Parameters:
    namefunc (function): The function whose output needs to be converted.

    Returns:
    function: A wrapper of the given function that returns bytestrings in Python 2.
    """
    def inner_func(*args, **kwargs):
        if sys.version_info[0] == 2:
            return namefunc(*args, **kwargs).encode('utf-8')
        else:
            return namefunc(*args, **kwargs)
    return inner_func
