    good_objects = 0

    try:
        for obj in self.iter_objects(self.root):
            num_objects += 1
            is_valid = True
            if validate_objects:
                if not self.is_valid_object(obj):
                    is_valid = False
            if check_digests and is_valid:
                if not self.check_object_digest(obj):
