def deep_merge_nodes(nodes):
    if not nodes:
        return []
    result = []
    for key, value in nodes:
        # Check if key is already in the result
        key_found = False
        for i, (existing_key, existing_value) in enumerate(result):
            # Compare keys by their string representation or value
            if existing_key.tag == 'tag:yaml.org,2002:str' and key.tag == 'tag:yaml.org,2002:str':
                if existing_key.value == key.value:
                    key_found = True
                    # If both are MappingNodes, merge them recursively
                    if hasattr(existing_value, 'value') and hasattr(value, 'value') and isinstance(existing_value.value, list) and isinstance(value.value, list):
                        # Check if they are MappingNodes by their tag
                        if existing_value.tag == 'tag:yaml.org,2002:map' and value.tag == 'tag:yaml.org,2002:map':
                            # Convert existing value to list, merge, and update the existing node
                            # We need to create a new merged value
                            merged_items = deep_merge_nodes(list(existing_value.value) + list(value.value))
                            # Update the existing_value with the merged items
                            existing_value.value = merged_items
                        else:
                            # Last wins for non-mapping or mismatched
                            result[i] = (key, value)
                    else:
                        # Last wins
                        result[i] = (key, value)
                    break
            # Handle non-string keys? The prompt implies ScalarNode keys which are usually strings in config.
            # If tag is not str, we might need to compare differently, but for this context, str is sufficient.
            # Let's also check if the tag is the same generally
            if existing_key.tag == key.tag and (not existing_key.tag.endswith(':str') or existing_key.value == key.value):
                 if existing_key.tag == 'tag:yaml.org,2002:str':
                     if existing_key.value == key.value:
                         pass # already handled above
                 else:
                     # Fallback for other types, likely exact match
                     if existing_key == key:
                         key_found = True
                         if existing_value.tag == 'tag:yaml.org,2002:map' and value.tag == 'tag:yaml.org,2002:map':
                             merged_items = deep_merge_nodes(list(existing_value.value) + list(value.value))
                             existing_value.value = merged_items
                         else:
                             result[i] = (key, value)
                         break
        if not key_found:
            result.append((key, value))
    return result

