def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    result = set()
    queue = {cls}

    while queue:
        current = queue.pop()
        for sub in current.__subclasses__():
            if sub not in result:
                result.add(sub)
                queue.add(sub)

    result.discard(cls)
    return result

