def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import os
        platform = 1 if os.name == 'posix' else 0
    if platform not in (0, 1):
        raise ValueError("platform must be 'this', 1 (POSIX), or 0 (Windows/CMD)")

    if platform == 1:
        # POSIX-style splitting
        # Use shlex for robust behavior
        import shlex
        return shlex.split(s, posix=True)
    else:
        # Windows/CMD-style splitting
        # Simplified: split on whitespace, respecting double quotes
        # Handles: "hello world" as one token, 'foo' as one token (without quotes)
        tokens = []
        current = []
        in_quotes = False
        quote_char = None
        i = 0
        while i < len(s):
            ch = s[i]
            if in_quotes:
                if ch == quote_char:
                    in_quotes = False
                else:
                    current.append(ch)
            else:
                if ch in ('"', "'"):
                    in_quotes = True
                    quote_char = ch
                elif ch.isspace():
                    if current:
                        tokens.append(''.join(current))
                        current = []
                else:
                    current.append(ch)
            i += 1
        if current:
            tokens.append(''.join(current))
        return tokens

def addignored(ignored):
    """ Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        # Check what files are ignored
        result = subprocess.run(['git', 'ls-files', '-o', '-i'], stdout=subprocess.PIPE)
