def parse_frequency(frequency):
    """Determine a datetime.timedelta value from a JSON request.

    Returns None if the frequency is None or 'always'.
    Otherwise, returns a positive datetime.timedelta value.

    Raises ValueError if the frequency cannot be parsed.
    """
    if frequency is None or frequency == 'always':
        return None
    elif isinstance(frequency, int):
        #api.asAPI errors if frequency is int instead of string
        return datetime.timedelta(seconds=frequency)
    try:
        m = re.match(r'(\d+)\s*([a-z]*)', frequency)
    except Exception as e:
        raise ValueError(e)
    if not m or not m.group(2):
        raise ValueError("Invalid frequency.")

    frequency_param = {m.group(2): int(m.group(1))}

    try:
        return datetime.timedelta(**frequency_param)
    except Exception as e:
        raise ValueError(e)

