def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                config_data = f.read()

            # Attempt to parse as JSON, YAML, or TOML
            try:
                # Try JSON first
                import json
                config = json.loads(config_data)
            except json.JSONDecodeError:
                try:
                    # Try YAML
                    import yaml
                    config = yaml.safe_load(config_data)
                    if not isinstance(config, dict):
                        raise ValueError("YAML config did not parse to a dictionary")
                except ImportError:
                    try:
                        # Try TOML
                        import toml
                        config = toml.loads(config_data)
                    except ImportError:
                        raise ValueError(f"Could not parse config file {filename} with available parsers")

            # Apply overrides if provided
            if overrides:
                for key, value in overrides.items():
                    if key in config:
                        config[key] = value

            configs[filename] = config

        except Exception as e:
            logger = logging.getLogger("ConfigLoader")
            record = logger.makeRecord(
                logger.name, 
                logging.ERROR, 
                filename, 
                0, 
                msg=f"Error loading config file {filename}: {str(e)}",
                args=(),
                exc_info=sys.exc_info()
            )
            errors.append(record)

    return configs, errors
