def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(iface, '__class__'):
        raise TypeError('iface must be a class')
    if not hasattr(candidate, '__class__'):
        raise TypeError('candidate must be a class')
    if tentative:
        # In tentative mode, just check if the interface method exists
        for name in dir(iface):
            if name.startswith('__') and name.endswith('__'):
                continue
            if not hasattr(candidate, name):
                return False
    else:
        # Strict mode: check method signatures
        for name in dir(iface):
            if name.startswith('__') and name.endswith('__'):
                continue
            iface_method = getattr(iface, name)
            cand_method = getattr(candidate, name, None)
            if cand_method is None:
                return False
            # Basic check: if it's callable in iface, it should be in candidate
            if callable(iface_method) and not callable(cand_method):
                return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        result = explicit_mc
    else:
        result = type
        for base in bases:
            if type(base) is not type:
                raise TypeError("metaclasses must inherit from type")
            if base.__class__ is not type:
                base_mc = base.__class__
                if isinstance(result, base_mc):
                    # The new metaclass is a candidate, and the current one passes.
                    pass
                elif isinstance(base_mc, result):
                    # The base's metaclass is a subclass of the current candidate, so use it.
                    result = base_mc
                else:
                    raise TypeError("metaclass conflict: the metaclass of a derived"
                                    " class must be a (non-strict) subclass"
                                    " of the metaclasses of all its bases")
    return result

def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self._counter:
            raise KeyError('dictionary is empty')
        key, freq = self._counter.popitem()
        return key, self._data[key]

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        try:
            last, node = self._map.popitem(last=True)
        except KeyError:
            raise KeyError('dictionary is empty')
        self._remove(node)
        return (last, node[1])

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError
    key = random.choice(list(keys(self)))
    return (key, self.pop(key))

