def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    path = request.path if hasattr(request, 'path') else None
    if path is None:
        return False

    # Matrix requests typically start with /_matrix/ or /_matrix/client/ or similar
    # A common heuristic is to check if the path starts with /_matrix/
    if isinstance(path, str):
        return path.startswith('/_matrix/')
    return False

