def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    document, code, exception = fetch_document(
        url=url,
        path="/.well-known/nodeinfo",
    )
    if exception:
        return None
    nodeinfo = parse_nodeinfo(document)
    if not nodeinfo:
        return None
    version = nodeinfo.get("version")
    if not version:
        return None
    server = nodeinfo.get("server")
    if not server:
        return None
    if document_path is None:
        document_path = nodeinfo.get("links", [{}])[0].get("href", "/nodeinfo/1.0")
    document, code, exception = fetch_document(url=url, path=document_path)
    if exception:
        return None
    return parse_nodeinfo(document)

def parse_diaspora_webfinger(document):
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html

    :param document: Document as a string
    :return: dict
    """
    try:
        # check for JSON first, since JSON is a subset of XRD
        subject, jwks = parse_json_webfinger(document)
        return {
            "subject": subject,
            "jwks": jwks,
            "links": parse_webfinger_links(document),
        }
    except Exception:
        return parse_xrd_webfinger(document)

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("try_retrieve_webfinger_document: invalid handle given: %s", handle)
        return None

    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        response = fetch_document(url)
        if response:
            return response
    except Exception:
        pass

    return None

