def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
            raise TypeError("Both cli_args and answer_file_args must be dictionaries")

        deprecated = 0
        for arg in answer_file_args:
            if arg in cli_args and cli_args[arg] is not None:
                # Check if the argument is in the list of deprecated arguments
                if arg in self.deprecated_args:
                    # If an alternative argument exists
                    if arg in self.deprecated_alternatives:
                        # Print a warning message, suggest using the alternative argument
                        print(f"Warning: Argument '{arg}' is deprecated. Please use '{self.deprecated_alternatives[arg]}' instead.")
                        # Optional: skip other validations or actions for this argument
                    else:
                        # Print a warning message if no alternative is provided
                        print(f"Warning: Argument '{arg}' is deprecated.")

                    # Mark the argument as deprecated
                    deprecated += 1

        # Inform the user if a significant number of deprecated arguments are used
        if deprecated > 0:
            print(f"A total of {deprecated} deprecated argument(s) has/have been used.")

