        if not isinstance(vars_dict, dict):
            return vars_dict

        # extra_vars is a list of dictionaries
        for extra_var in extra_vars:
            if isinstance(extra_var, dict):
                # Handle nested dictionaries
                for key, value in extra_var.items():
                    if key in vars_dict and isinstance(vars_dict[key], dict) and isinstance(value, dict):
