def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list")
    if vars_dict is not None and not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict or None")

    cmd = ["ansible-playbook"] + list(cli_args)

    if vars_dict is not None and vars_dict:
        extra_vars = " ".join(f"{k}={v}" for k, v in vars_dict.items())
        cmd += ["--extra-vars", extra_vars]

    try:
        import subprocess
        import json

        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            cwd=str(ir_workspace.path) if hasattr(ir_workspace, "path") else None
        )

        logs = ir_plugin.logger or None
        if logs:
            logs.info(f"Running command: {' '.join(cmd)}")
            if result.stdout:
                logs.info(f"stdout:\n{result.stdout}")
            if result.stderr:
                logs.info(f"stderr:\n{result.stderr}")

        if result.returncode == 0:
            try:
                # Try to parse JSON from stdout if needed, otherwise return basic result
                return json.loads(result.stdout) if result.stdout.strip().startswith('{') else {
                    "returncode": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                }
            except json.JSONDecodeError:
                return {
                    "returncode": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                }
        else:
            return {
                "returncode": result.returncode,
                "stdout": result.stdout,
                "stderr": result.stderr,
                "error": f"Ansible command exited with code {result.returncode}"
            }

    except Exception as e:
        if ir_plugin and hasattr(ir_plugin, 'logger'):
            ir_plugin.logger.error(f"Error running playbook: {str(e)}")
        return {
            "error": str(e),
            "returncode": -1,
            "stdout": "",
            "stderr": str(e)
        }
