            return

        # Iterate through the config and cast values in values_dict
        for arg_name, arg_info in config.items():
            if arg_name in values_dict:
                value = values_dict[arg_name]
                if value is None:
                    continue
                # Determine the type to cast to
                if hasattr(arg_info, 'type') and arg_info.type is not None:
                    try:
                        # If it's a type like int, float, bool, etc.
                        values_dict[arg_name] = arg_info.type(value)
                    except (ValueError, TypeError):
                        # If type conversion fails, keep original value
                        pass
                elif hasattr(arg_info, 'cast') and callable(getattr(arg_info, 'cast', None)):
                    try:
                        values_dict[arg_name] = arg_info.cast(value)
                    except (ValueError, TypeError):
