def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_path):
        return {}

    try:
        with open(spec_path, 'r') as f:
            spec = json.load(f)
    except (IOError, json.JSONDecodeError):
        return {}

    def flatten(obj, prefix=''):
        items = {}
        for key, value in obj.items():
            new_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                items.update(flatten(value, new_key))
            else:
                items[new_key] = value
        return items

    return flatten(spec)
